 98→    throw new Error(`Invalid image input: unsupported mime type "${mimeType}"`);
 99→  }
100→
101→  const normalized = base64Data.replace(/\s+/g, '');
102→  if (normalized.length === 0) {
103→    throw new Error('Invalid image input: empty image payload');
104→  }
105→
106→  const decodedBytes = estimateBase64SizeBytes(normalized);
107→  if (decodedBytes > MAX_IMAGE_BYTES) {
108→    throw new Error(`Invalid image input: payload too large (${decodedBytes} bytes, max ${MAX_IMAGE_BYTES})`);
109→  }
110→}
111→
112→function estimateBase64SizeBytes(base64Data: string): number {
113→  const padding = base64Data.endsWith('==') ? 2 : base64Data.endsWith('=') ? 1 : 0;
114→  return Math.floor((base64Data.length * 3) / 4) - padding;
